#import "ABMCShortcutListController.h"
#import "ABMCUIHelpers.h"
#import <sqlite3.h>
static BOOL UUIDOK(NSString*v){return[v isKindOfClass:NSString.class]&&[[NSUUID alloc]initWithUUIDString:v]!=nil;}
@interface ABMCShortcutListController ()<UISearchBarDelegate>@end
@implementation ABMCShortcutListController{NSString*_key,*_query,*_expanded;NSArray*_all,*_folders;}
- (instancetype)initWithPreferenceKey:(NSString*)key{if((self=[super initWithStyle:UITableViewStyleInsetGrouped])){_key=[key copy];self.title=@"指令列表";}return self;}
- (void)viewDidLoad{[super viewDidLoad];_query=@"";self.tableView.rowHeight=58;[self updateHeader];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"清空" style:UIBarButtonItemStylePlain target:self action:@selector(clearAll)];[self reloadData];}
- (void)updateHeader{UIView*h=ABMCSelectedActionsBanner(_key);UISearchBar*s=[[UISearchBar alloc]initWithFrame:CGRectMake(8,106,h.bounds.size.width-16,56)];s.placeholder=@"搜索快捷指令";s.delegate=self;CGRect f=h.frame;f.size.height=168;h.frame=f;[h addSubview:s];self.tableView.tableHeaderView=h;}
- (void)clearAll{ABMCStoreSelectedActions(_key,@[]);[self updateHeader];[self.tableView reloadData];}
- (NSString*)folderReferenceColumn:(sqlite3*)db { sqlite3_stmt*s=NULL;NSString*answer=nil;if(sqlite3_prepare_v2(db,"PRAGMA table_info(ZSHORTCUT)",-1,&s,NULL)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW){NSString*n=[NSString stringWithUTF8String:(const char*)sqlite3_column_text(s,1)];if([n rangeOfString:@"FOLDER" options:NSCaseInsensitiveSearch].location!=NSNotFound){answer=n;break;}}if(s)sqlite3_finalize(s);return answer;}
- (void)reloadData{NSMutableDictionary*work=[NSMutableDictionary dictionary],*folders=[NSMutableDictionary dictionary];for(NSString*path in @[@"/private/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/var/mobile/Library/Shortcuts/Shortcuts.sqlite"]){sqlite3*db=NULL;if(sqlite3_open_v2(path.UTF8String,&db,SQLITE_OPEN_READONLY|SQLITE_OPEN_NOMUTEX,NULL)!=SQLITE_OK){if(db)sqlite3_close(db);continue;}NSString *folderFK=[self folderReferenceColumn:db];sqlite3_stmt*s=NULL;if(sqlite3_prepare_v2(db,"SELECT name FROM sqlite_master WHERE type='table' AND upper(name) LIKE '%FOLDER%'",-1,&s,NULL)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW){NSString*table=[NSString stringWithUTF8String:(const char*)sqlite3_column_text(s,0)];NSString*sql=[NSString stringWithFormat:@"SELECT Z_PK,ZNAME FROM %@ WHERE ZNAME IS NOT NULL",table];sqlite3_stmt*r=NULL;if(sqlite3_prepare_v2(db,sql.UTF8String,-1,&r,NULL)==SQLITE_OK)while(sqlite3_step(r)==SQLITE_ROW){NSString*ident=[NSString stringWithFormat:@"%lld",sqlite3_column_int64(r,0)];const char*n=(const char*)sqlite3_column_text(r,1);if(n)folders[ident]=[@{@"id":ident,@"name":[NSString stringWithUTF8String:n],@"items":[NSMutableArray array]}mutableCopy];}if(r)sqlite3_finalize(r);}if(s)sqlite3_finalize(s);
NSString *fk=folderFK.length?[NSString stringWithFormat:@",x.%@",folderFK]:@"";NSString*q=[NSString stringWithFormat:@"SELECT x.ZNAME,x.ZWORKFLOWID,COALESCE(i.ZGLYPHNUMBER,0),COALESCE(i.ZBACKGROUNDCOLORVALUE,0)%@ FROM ZSHORTCUT x LEFT JOIN ZSHORTCUTICON i ON i.Z_PK=x.ZICON WHERE x.ZNAME IS NOT NULL AND x.ZWORKFLOWID IS NOT NULL AND COALESCE(x.ZTOMBSTONED,0)=0",fk];s=NULL;if(sqlite3_prepare_v2(db,q.UTF8String,-1,&s,NULL)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW){const char*n=(const char*)sqlite3_column_text(s,0),*i=(const char*)sqlite3_column_text(s,1);if(!n||!i)continue;NSString*name=[NSString stringWithUTF8String:n],*ident=[[NSString stringWithUTF8String:i]uppercaseString];if(!name.length||!UUIDOK(ident))continue;NSMutableDictionary*item=[@{@"name":name,@"id":ident,@"glyph":@(sqlite3_column_int64(s,2)),@"color":@(sqlite3_column_int64(s,3))}mutableCopy];work[ident]=item;if(folderFK.length&&sqlite3_column_type(s,4)!=SQLITE_NULL){NSString*fid=[NSString stringWithFormat:@"%lld",sqlite3_column_int64(s,4)];if(folders[fid])[folders[fid][@"items"] addObject:item];}}if(s)sqlite3_finalize(s);sqlite3_close(db);}
_all=[work.allValues sortedArrayUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return[a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];}];_folders=[folders.allValues sortedArrayUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return[a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];}];[self.tableView reloadData];}
- (NSArray*)shown{if(_expanded.length){for(NSDictionary*f in _folders)if([f[@"id"]isEqual:_expanded])return f[@"items"];return @[];}return!_query.length?_all:[_all filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary*x,NSDictionary*b){return[x[@"name"] localizedCaseInsensitiveContainsString:_query];}]];}
- (NSInteger)numberOfSectionsInTableView:(UITableView*)t{return 2;}
- (NSString*)tableView:(UITableView*)t titleForHeaderInSection:(NSInteger)s{return s==0?@"文件夹":(_expanded.length?@"文件夹内快捷指令":@"全部快捷指令");}
- (NSInteger)tableView:(UITableView*)t numberOfRowsInSection:(NSInteger)s{return s==0?_folders.count:self.shown.count?:1;}
- (UITableViewCell*)tableView:(UITableView*)t cellForRowAtIndexPath:(NSIndexPath*)p{UITableViewCell*c=[t dequeueReusableCellWithIdentifier:@"sc"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"sc"];if(p.section==0){NSDictionary*f=_folders[p.row];ABMCApplyLargeIcon(c,ABMCTintedIcon(@"folder.fill",nil));c.textLabel.text=f[@"name"];c.textLabel.font=[UIFont systemFontOfSize:18];c.detailTextLabel.text=[NSString stringWithFormat:@"%lu 项",(unsigned long)[f[@"items"]count]];c.accessoryType=[f[@"id"]isEqual:_expanded]?UITableViewCellAccessoryDetailButton:UITableViewCellAccessoryDisclosureIndicator;return c;}NSArray*v=self.shown;if(!v.count){c.textLabel.text=_expanded.length?@"该文件夹没有可读取的快捷指令":@"未读取到快捷指令";c.detailTextLabel.text=nil;return c;}NSDictionary*x=v[p.row];NSString*k=[@"shortcut." stringByAppendingString:x[@"id"]],*token=ABMCDisplayIconToken(k,@"");ABMCApplyLargeIcon(c,ABMCTintedIcon(token,nil)?:ABMCWorkflowIconImage([x[@"glyph"]integerValue],[x[@"color"]longLongValue]));c.textLabel.font=[UIFont systemFontOfSize:18];c.textLabel.text=ABMCDisplayTitle(k,x[@"name"]);NSString*a=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",x[@"id"],x[@"name"],x[@"glyph"],x[@"color"]];c.accessoryType=[ABMCSelectedActions(_key)containsObject:a]?UITableViewCellAccessoryCheckmark:0;ABMCInstallPresentationLongPress(c,self,k,c.textLabel.text,token,^{[self.tableView reloadData];});return c;}
- (void)tableView:(UITableView*)t didSelectRowAtIndexPath:(NSIndexPath*)p{if(p.section==0){NSDictionary*f=_folders[p.row];_expanded=[f[@"id"]copy];NSArray*items=f[@"items"];if(items.count){NSMutableArray*all=[ABMCSelectedActions(_key)mutableCopy];for(NSDictionary*x in items){if(all.count>=8)break;[all addObject:[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",x[@"id"],x[@"name"],x[@"glyph"],x[@"color"]]];}ABMCStoreSelectedActions(_key,all);[self updateHeader];}[t reloadData];return;}NSArray*v=self.shown;if(!v.count)return;NSDictionary*x=v[p.row];NSString*a=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",x[@"id"],x[@"name"],x[@"glyph"],x[@"color"]];NSMutableArray*z=[ABMCSelectedActions(_key)mutableCopy];if([z containsObject:a])[z removeObject:a];else if(z.count<8)[z addObject:a];else return;ABMCStoreSelectedActions(_key,z);[self updateHeader];[t reloadData];}
- (void)searchBar:(UISearchBar*)s textDidChange:(NSString*)text{_query=[text copy]?:@"";_expanded=nil;[self.tableView reloadData];}@end
